#include <stdio.h>

int main(void) {
    int a[3] = {1, 2, 3};
    int b[3] = {{b1}, {b2}, {b3}};

    for (int i = 0; i < 3; i++) {
        a[i] = b[i];
    }
    printf("%d %d %d\n", a[0], a[1], a[2]);
    return 0;
}
